begin;
alter table public.services add column if not exists description_ar text, add column if not exists benefits_ar text, add column if not exists deliverables_ar text, add column if not exists workflow_ar text, add column if not exists pricing_ar text;
alter table public.portfolio_projects add column if not exists title_ar text, add column if not exists description_ar text, add column if not exists category_ar text, add column if not exists industry_ar text, add column if not exists challenge_ar text, add column if not exists solution_ar text, add column if not exists results_ar text, add column if not exists services_provided_ar text, add column if not exists external_url text;
alter table public.testimonials add column if not exists quote_ar text;
create or replace view public.published_services with (security_barrier=true) as select id,name,name_ar,slug,division,description,benefits,deliverables,workflow,case when show_pricing then pricing else null end as pricing,show_pricing,image_url,featured,sort_order,description_ar,benefits_ar,deliverables_ar,workflow_ar,case when show_pricing then pricing_ar else null end as pricing_ar from public.services where published=true;
create or replace view public.published_portfolio with (security_barrier=true) as select id,title,slug,client_name,category,industry,description,challenge,solution,services_provided,technologies,results,project_date,thumbnail_url,video_url,featured,sort_order,title_ar,description_ar,category_ar,industry_ar,challenge_ar,solution_ar,results_ar,services_provided_ar,external_url from public.portfolio_projects where published=true;
create or replace view public.published_testimonials with (security_barrier=true) as select id,name,company,quote,quote_ar from public.testimonials where published=true;
create or replace view public.published_settings with (security_barrier=true) as select key,value from public.website_settings where is_public=true and (key in ('hero_title','hero_description','hero_title_ar','hero_description_ar','address','address_ar','contact_email','contact_phone','footer_description','footer_description_ar','primary_color','secondary_color','accent_color','site_description','site_title') or key like 'social\_%' escape '\' or key like 'page\_%' escape '\');
-- View ownership, existing SELECT grants, base-table RLS and all write scopes remain unchanged.
commit;
